(556920, 56809, 4321, '<td valign="top">This is lovely.  I would have cropped the dark top just above the bucket.</td>', 'This is lovely.  I would have cropped the dark top just above the bucket.', '2004-01-26 00:55:50.000000', NULL, 1),
(556922, 56115, 4321, '<td valign="top">Beautiful</td>', 'Beautiful', '2004-01-26 00:56:44.000000', NULL, 1),
(556923, 56929, 4321, '<td valign="top">My favorite so far</td>', 'My favorite so far', '2004-01-26 00:57:01.000000', NULL, 1),
(556925, 56377, 9073, '<td valign="top">The challenge states that the primary light source should be non-stationary. I know that we could argue about the movement of the sun, but, for now, I have to conclude that this shot doesn''t fit the topic. Nice lines, though. 2</td>', 'The challenge states that the primary light source should be non-stationary. I know that we could argue about the movement of the sun, but, for now, I have to conclude that this shot doesn''t fit the topic. Nice lines, though. 2', '2004-01-26 00:58:09.000000', NULL, 1),
(556926, 57012, 4321, '<td valign="top">Beautiful color, could have use some cropping of the black part, it is a little overwhelming</td>', 'Beautiful color, could have use some cropping of the black part, it is a little overwhelming', '2004-01-26 00:58:13.000000', NULL, 1),
(556928, 56054, 4321, '<td valign="top">Very cool</td>', 'Very cool', '2004-01-26 00:58:56.000000', NULL, 1),
(556929, 56707, 9073, '<td valign="top">A nice idea, well executed. 7</td>', 'A nice idea, well executed. 7', '2004-01-26 00:59:51.000000', NULL, 1),
(556931, 56645, 6100, '<td valign="top">This appears too "hot" with the highlights. Such a solid shadow implies that you didn''t move the light very much if at all. Composition is fine although it seems too tightly cropped.</td>', 'This appears too "hot" with the highlights. Such a solid shadow implies that you didn''t move the light very much if at all. Composition is fine although it seems too tightly cropped.', '2004-01-26 01:00:56.000000', NULL, 1),
