(556937, 57037, 9073, '<td valign="top">Simply lovely. 9</td>', 'Simply lovely. 9', '2004-01-26 01:06:46.000000', NULL, 1),
(556952, 55933, 9073, '<td valign="top">This works. The subject and the challenge go so well together. You''ve really brought out the demon-character with the moving light treatment. I''d have given a higher score had the gargoyle been much lower in the frame. That would really have brought out the ''waiting to spring into action'' feeling here. 7</td>', 'This works. The subject and the challenge go so well together. You''ve really brought out the demon-character with the moving light treatment. I''d have given a higher score had the gargoyle been much lower in the frame. That would really have brought out the ''waiting to spring into action'' feeling here. 7', '2004-01-26 01:31:26.000000', NULL, 1),
(556956, 57046, 9073, '<td valign="top">Funny. We''ve all been there - I mean in the loo with our cameras. I wonder what our partners think?</td>', 'Funny. We''ve all been there - I mean in the loo with our cameras. I wonder what our partners think?', '2004-01-26 01:37:22.000000', NULL, 1),
