(557861, 56933, 10047, '<td valign="top">Awsome effect! Nice colors, contrast, and compostion.</td>', 'Awsome effect! Nice colors, contrast, and compostion.', '2004-01-26 13:50:09.000000', NULL, 1),
(557862, 57012, 10047, '<td valign="top">Beautiful shot. Really well done. Nice colors, composition, and fade to black. Congrats.</td>', 'Beautiful shot. Really well done. Nice colors, composition, and fade to black. Congrats.', '2004-01-26 13:51:18.000000', NULL, 1),
(557863, 57041, 15642, '<td valign="top">Very interesting. Looks painting-like. Way to attack the challenge.</td>', 'Very interesting. Looks painting-like. Way to attack the challenge.', '2004-01-26 13:51:35.000000', NULL, 1),
(557867, 57026, 15642, '<td valign="top">Nice reflection, but not much else of interest here.</td>', 'Nice reflection, but not much else of interest here.', '2004-01-26 13:52:33.000000', NULL, 1),
(557868, 56825, 327, '<td valign="top">Neat shot, love the colors.</td>', 'Neat shot, love the colors.', '2004-01-26 13:52:50.000000', NULL, 1),
(557869, 56541, 15642, '<td valign="top">Not terribly interesting for me.</td>', 'Not terribly interesting for me.', '2004-01-26 13:52:59.000000', NULL, 1),
(557870, 56415, 10047, '<td valign="top">Beautiful shot! Nice colors, composition, and fade to black. I realyl like the clarity and detail. Did you use a mister bottle for the water droplets?</td>', 'Beautiful shot! Nice colors, composition, and fade to black. I realyl like the clarity and detail. Did you use a mister bottle for the water droplets?', '2004-01-26 13:53:26.000000', NULL, 1);
