(557890, 55933, 327, '<td valign="top">Beautiful tones. Good luck in the challenge.</td>', 'Beautiful tones. Good luck in the challenge.', '2004-01-26 14:00:09.000000', NULL, 1),
(557891, 56744, 10047, '<td valign="top">Maybe shouldn''t have illuminated the whole figure. If you left a part of it dark then you could see the effect and the fade to black. The marble also seems a little out of focus.</td>', 'Maybe shouldn''t have illuminated the whole figure. If you left a part of it dark then you could see the effect and the fade to black. The marble also seems a little out of focus.', '2004-01-26 14:00:12.000000', NULL, 1),
(557892, 56809, 15642, '<td valign="top">Wow. Beautifully lit. Nicely composed, as well. 9</td>', 'Wow. Beautifully lit. Nicely composed, as well. 9', '2004-01-26 14:00:12.000000', NULL, 1),
(557893, 57023, 327, '<td valign="top">Compliments to you and a very good shot....neat light and cool blue.</td>', 'Compliments to you and a very good shot....neat light and cool blue.', '2004-01-26 14:01:10.000000', NULL, 1),
(557894, 56563, 7291, '<td valign="top">Extra points for making me laugh!  I actually think this is one of the better ones of the challenge because it''s simple, effective and, of course, was painted with light.</td>', 'Extra points for making me laugh!  I actually think this is one of the better ones of the challenge because it''s simple, effective and, of course, was painted with light.', '2004-01-26 14:01:26.000000', NULL, 1),
(557895, 56933, 327, '<td valign="top">Very cool blue and red. I love the composition.</td>', 'Very cool blue and red. I love the composition.', '2004-01-26 14:02:52.000000', NULL, 1),
(557897, 56933, 15642, '<td valign="top">I believe Bond prefers a lemon peel over an olive in his martinis, but nicely done just the same.</td>', 'I believe Bond prefers a lemon peel over an olive in his martinis, but nicely done just the same.', '2004-01-26 14:04:02.000000', NULL, 1),
(557898, 56647, 15642, '<td valign="top">Interesting use of light.</td>', 'Interesting use of light.', '2004-01-26 14:05:25.000000', NULL, 1),
(557900, 57010, 15642, '<td valign="top">The black background adds a bit of sterility against the shells.</td>', 'The black background adds a bit of sterility against the shells.', '2004-01-26 14:06:14.000000', NULL, 1),
(557901, 57023, 15642, '<td valign="top">Very nice. A very elegant "tornado."</td>', 'Very nice. A very elegant "tornado."', '2004-01-26 14:07:08.000000', NULL, 1),
(557903, 56574, 15642, '<td valign="top">The monotone effect here hurts the image. I''d like to see the pic without the effect.</td>', 'The monotone effect here hurts the image. I''d like to see the pic without the effect.', '2004-01-26 14:08:01.000000', NULL, 1),
(557905, 56547, 15642, '<td valign="top">Not terribly interesting for me.</td>', 'Not terribly interesting for me.', '2004-01-26 14:09:44.000000', NULL, 1),
